func TestQuoteMatchesGNU(t *testing.T) {
	for _, tt := range gnuQuotes {
		for style, want := range tt.want {
			o := Options{Style: Style(style), LeftQuote: UTF8LeftQuote, RightQuote: UTF8RightQuote}
			if o.Style == Escape {
				// ls escapes a space too in this style.
				o.Also = " "
			}
			if got := Quote(tt.name, o); got != want {
				t.Errorf("%s %q = %q, want %q", Names[style], tt.name, got, want)
			}
		}
	}
}

func TestCLocaleQuotes(t *testing.T) {
	if got := Quote("a", Options{Style: Locale}); got != "'a'" {
		t.Errorf("locale = %q", got)
	}
	if got := Quote("a", Options{Style: CLocale}); got != `"a"` {
		t.Errorf("clocale = %q", got)
	}
}
